"""Bench chain fixtures generated by the v1.0.15 build: heavy.capy and vector.capy for each canvas size, and the gigapixel set.

The gigapixel set builds in its own v1.0.15 tree with bench-patches/v1.0.15-gigapixel-fixtures.patch, which lifts the
16,384-tile save limit that giga-layers.capy exceeds; Pillow turns the generated square photo into giga-square.jpg.
Usage: bench_fixtures.py [WIDTHxHEIGHT | gigapixel ...]   (default: every tier canvas)
"""
import hashlib
import json
import os
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path

REPO = Path(__file__).resolve().parents[2]
SOURCE = Path('/mnt/localssd/capy-bench/src/v1.0.15')
GIGAPIXEL_SOURCE = Path('/mnt/localssd/capy-bench/src/v1.0.15-gigapixel')
GIGAPIXEL_PATCH = Path(__file__).with_name('bench-patches') / 'v1.0.15-gigapixel-fixtures.patch'
FIXTURES = Path.home() / 'capy-bench' / 'fixtures'
GIGAPIXEL_FIXTURES = Path('/mnt/localssd/capy-bench/fixtures/gigapixel')
TIERS = [(4248, 2832), (6000, 4000), (7360, 4912), (9504, 6336)]
NAMES = ('heavy', 'vector')
GIGAPIXEL = {'giga-square': 'giga-square.jpg', 'giga-panorama': 'giga-panorama.png', 'giga-layers': 'giga-layers.capy'}
JPEG_QUALITY = 90
GENERATOR = ('crates/layer-core/examples/bench_fixtures.rs', 'crates/layer-core/examples/capy_fixture/mod.rs')


def sha256(path):
    digest = hashlib.sha256()
    with open(path, 'rb') as file:
        for block in iter(lambda: file.read(1 << 20), b''):
            digest.update(block)
    return digest.hexdigest()


def generator(tree=SOURCE, patch=None):
    if not tree.exists():
        subprocess.run(['git', '-C', str(REPO), 'worktree', 'add', '--detach', str(tree), 'v1.0.15'], check=True)
    if patch and subprocess.run(['git', '-C', str(tree), 'apply', '--reverse', '--check', str(patch)], capture_output=True).returncode:
        subprocess.run(['git', '-C', str(tree), 'apply', str(patch)], check=True)
    for path in GENERATOR:
        source, overlay = REPO / path, tree / path
        if not overlay.exists() or overlay.read_bytes() != source.read_bytes():
            overlay.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(source, overlay)
    target = tree / 'target'
    subprocess.run(['cargo', 'build', '--locked', '--release', '-p', 'layer-core', '--example', 'bench_fixtures'],
                   cwd=tree, check=True, env=dict(os.environ, CARGO_TARGET_DIR=str(target)))
    return target / 'release' / 'examples' / 'bench_fixtures'


def jpeg(png, path):
    from PIL import Image
    Image.MAX_IMAGE_PIXELS = None
    with Image.open(png) as image:
        image.save(path, 'JPEG', quality=JPEG_QUALITY)


def ensure(directory, files, arguments, *build):
    manifest_path = directory / 'manifest.json'
    manifest = json.loads(manifest_path.read_text()) if manifest_path.exists() else {}
    paths = {name: directory / file for name, file in files.items()}
    stale = [name for name, path in paths.items() if not path.exists() or manifest.get(path.name) != sha256(path)]
    if stale:
        directory.mkdir(parents=True, exist_ok=True)
        with tempfile.TemporaryDirectory(dir=directory) as scratch:
            subprocess.run([str(generator(*build)), scratch, *arguments], check=True)
            for name in stale:
                made = Path(scratch) / paths[name].name
                if made.suffix == '.jpg':
                    jpeg(made.with_suffix('.png'), made)
                os.replace(made, paths[name])
                manifest[paths[name].name] = sha256(paths[name])
        partial = manifest_path.with_suffix('.partial')
        partial.write_text(json.dumps(manifest, indent=2, sort_keys=True) + '\n')
        os.replace(partial, manifest_path)
    return paths


def ensure_fixtures(width, height):
    return ensure(FIXTURES / f'{width}x{height}', {name: f'{name}.capy' for name in NAMES}, [str(width), str(height)])


def ensure_gigapixel():
    return ensure(GIGAPIXEL_FIXTURES, GIGAPIXEL, ['gigapixel'], GIGAPIXEL_SOURCE, GIGAPIXEL_PATCH)


def fixture(name, width, height):
    return ensure_gigapixel()[name] if name in GIGAPIXEL else ensure_fixtures(width, height)[name]


def file_name(name):
    return GIGAPIXEL.get(name, f'{name}.capy')


if __name__ == '__main__':
    for size in sys.argv[1:] or [f'{width}x{height}' for width, height in TIERS]:
        paths = ensure_gigapixel() if size == 'gigapixel' else ensure_fixtures(*map(int, size.split('x')))
        for name, path in paths.items():
            print(f'{size} {name} {path} {path.stat().st_size / 1e6:.1f} MB')
